import json
import shutil
import subprocess

import pytest
import torch

from nivra.data.ingest import IngestError, IngestOptions, ingest_folder, inspect_dataset
from nivra.data.shards import ShardDataset, verify_shards

pytestmark = pytest.mark.skipif(shutil.which("ffmpeg") is None or shutil.which("ffprobe") is None, reason="ffmpeg missing")

PROV = {"source": "synthetic ffmpeg lavfi sources", "license": "CC0-1.0", "license_url": "https://creativecommons.org/publicdomain/zero/1.0/",
        "permission": "generated by the test-suite", "collected": "2026-01-01", "contains_people": False, "consent": "n/a"}


def _ff(*args):
    r = subprocess.run(["ffmpeg", "-hide_banner", "-nostdin", "-v", "error", "-y", *args], capture_output=True)
    assert r.returncode == 0, r.stderr.decode()


def _two_scene(path, a, b, size="640x360", each=3, rate=24):
    _ff("-t", str(each), "-f", "lavfi", "-i", f"{a}=s={size}:r={rate}", "-t", str(each), "-f", "lavfi", "-i", f"{b}=s={size}:r={rate}",
        "-filter_complex", "[0:v][1:v]concat=n=2:v=1:a=0,format=yuv420p", "-c:v", "libx264", "-preset", "ultrafast", "-g", "12", str(path))


def _one(path, src, size="640x360", dur=3, rate=24, extra=()):
    _ff("-t", str(dur), "-f", "lavfi", "-i", f"{src}=s={size}:r={rate}", *extra, "-pix_fmt", "yuv420p", "-c:v", "libx264", "-preset", "ultrafast", str(path))


@pytest.fixture(scope="module")
def folder(tmp_path_factory):
    d = tmp_path_factory.mktemp("videos")
    _two_scene(d / "cut.mp4", "testsrc2", "mandelbrot")        # two scenes of 3 s
    shutil.copy(d / "cut.mp4", d / "cut_copy.mp4")                 # exact duplicate content
    _one(d / "bars_static.mp4", "smptebars")                       # static
    _ff("-f", "lavfi", "-i", "color=c=black:s=640x360:r=24:d=3", "-pix_fmt", "yuv420p", str(d / "black.mp4"))
    _one(d / "tiny_res.mp4", "testsrc", size="160x90")
    _one(d / "short.mp4", "rgbtestsrc", dur=1)
    (d / "corrupt.mp4").write_bytes(b"this is not a video" * 100)
    _one(d / "nocap.mp4", "cellauto")
    for stem, cap in (("cut", "a test pattern that cuts to a fractal"), ("cut_copy", "same clip again"), ("bars_static", "colour bars"),
                      ("black", "black"), ("tiny_res", "small"), ("short", "short"), ("corrupt", "bad")):
        (d / f"{stem}.txt").write_text(cap, encoding="utf-8")
    (d / "PROVENANCE.json").write_text(json.dumps(PROV))
    return d


@pytest.fixture(scope="module")
def ds(folder, tmp_path_factory):
    out = tmp_path_factory.mktemp("ds")
    s = ingest_folder(folder, out, IngestOptions(bucket="256p2s", val_fraction=0.0), log=lambda *_: None)
    return out, s


def test_requires_provenance(folder, tmp_path):
    empty = tmp_path / "in"
    empty.mkdir()
    shutil.copy(folder / "cut.mp4", empty / "a.mp4")
    (empty / "a.txt").write_text("x")
    with pytest.raises(IngestError, match="PROVENANCE.json"):
        ingest_folder(empty, tmp_path / "out", log=lambda *_: None)
    assert not (tmp_path / "out").exists()
    bad = dict(PROV)
    del bad["consent"]
    (empty / "PROVENANCE.json").write_text(json.dumps(bad))
    with pytest.raises(IngestError, match="consent"):
        ingest_folder(empty, tmp_path / "out", log=lambda *_: None)
    bad = dict(PROV, contains_people=True, consent="")
    (empty / "PROVENANCE.json").write_text(json.dumps(bad))
    with pytest.raises(IngestError, match="consent"):
        ingest_folder(empty, tmp_path / "out", log=lambda *_: None)


def test_scene_split_frames_and_shape(ds):
    out, s = ds
    rows = [json.loads(l) for l in (out / "manifest.jsonl").read_text(encoding="utf-8").splitlines()]
    cut = [r for r in rows if r["source_file"] == "cut.mp4"]
    assert {r["scene_index"] for r in cut} == {0, 1}, "scene cut at 3 s must be found"
    window = 17 / 8
    for r in cut:
        assert (r["frames"], r["width"], r["height"], r["fps"]) == (17, 448, 256, 8.0)
        assert r["end"] - r["start"] == pytest.approx(window, abs=1e-3)
        assert not (r["start"] < 3.0 < r["end"]), "no clip may straddle the cut"
    assert r["provenance"]["license"] == "CC0-1.0" and r["lang"] == "und"
    d = ShardDataset(out, split=None)
    video, cap, meta = d[0]
    assert video.dtype == torch.uint8 and tuple(video.shape) == (17, 256, 448, 3)
    assert cap == "a test pattern that cuts to a fractal" and meta["id"] == rows[0]["id"]
    assert ShardDataset.to_float(video).shape == (3, 17, 256, 448)
    assert float(video.float().std()) > 5


def test_rejections_and_dedup(ds):
    out, s = ds
    rj = {(f["file"], f["reason"]) for f in s["rejected_files"]}
    assert ("cut_copy.mp4", "duplicate") in rj
    assert ("bars_static.mp4", "static") in rj
    assert ("black.mp4", "black") in rj
    assert ("tiny_res.mp4", "resolution_too_low") in rj
    assert ("short.mp4", "too_short") in rj
    assert ("corrupt.mp4", "corrupt") in rj
    assert ("nocap.mp4", "no_caption") in rj
    assert not any(json.loads(l)["source_file"] in ("cut_copy.mp4", "black.mp4") for l in (out / "manifest.jsonl").read_text().splitlines())


def test_frame_rule_per_bucket():
    from nivra.data.ingest.pipeline import BUCKETS
    for b, (w, h, f) in {"256p2s": (448, 256, 17), "480p4s": (854, 480, 121), "720p8s": (1280, 720, 241)}.items():
        assert (BUCKETS[b].width, BUCKETS[b].height, BUCKETS[b].frames) == (w, h, f) and (f - 1) % 8 == 0


def test_480p_bucket_resize_and_crop(tmp_path):
    src = tmp_path / "in"
    src.mkdir()
    _one(src / "wide.mp4", "testsrc2", size="1280x400", dur=5, rate=30)           # wider than 16:9 -> center crop
    (src / "wide.txt").write_text("wide testsrc", encoding="utf-8")
    (src / "PROVENANCE.json").write_text(json.dumps(PROV))
    s = ingest_folder(src, tmp_path / "o", IngestOptions(bucket="480p4s", allow_upscale=True, scene_threshold=None, val_fraction=0.0),
                      log=lambda *_: None)
    assert s["clips"] == 1 and s["frames"] == 121
    v, c, m = next(iter(ShardDataset(tmp_path / "o", split=None)))
    assert tuple(v.shape) == (121, 480, 854, 3) and m["end"] - m["start"] == pytest.approx(121 / 30, abs=1e-3)


def test_manifest_and_fingerprint_deterministic(folder, ds, tmp_path):
    out, s = ds
    s2 = ingest_folder(folder, tmp_path / "again", IngestOptions(bucket="256p2s", val_fraction=0.0), log=lambda *_: None)
    assert s2["fingerprint"] == s["fingerprint"]
    assert (tmp_path / "again" / "manifest.jsonl").read_bytes() == (out / "manifest.jsonl").read_bytes()
    assert [x["sha256"] for x in s2["shards"]] == [x["sha256"] for x in s["shards"]]


def test_inspect_and_verify_detect_corruption(ds, tmp_path):
    out, s = ds
    rep = inspect_dataset(out)
    assert rep["ok"] and rep["clips"] == s["clips"] and rep["per_license"] == {"CC0-1.0": s["clips"]}
    copy = tmp_path / "copy"
    shutil.copytree(out, copy)
    shard = copy / s["shards"][0]["file"]
    b = bytearray(shard.read_bytes())
    b[-5] ^= 0xFF
    shard.write_bytes(bytes(b))
    assert any("checksum" in p for p in verify_shards(copy))
    assert not inspect_dataset(copy)["ok"]


def test_max_clips_and_small_shards(folder, tmp_path):
    one_clip = 17 * 256 * 448 * 3
    s = ingest_folder(folder, tmp_path / "m", IngestOptions(val_fraction=0.0, shard_bytes=one_clip), log=lambda *_: None)
    assert s["clips"] == 2 and [x["clips"] for x in s["shards"]] == [1, 1]            # one clip per shard
    assert len(ShardDataset(tmp_path / "m", split="train", verify=True)) == 2
    s1 = ingest_folder(folder, tmp_path / "m1", IngestOptions(val_fraction=0.0, max_clips=1), log=lambda *_: None)
    assert s1["clips"] == 1


def test_refuses_nonempty_output(folder, ds, tmp_path):
    out, _ = ds
    with pytest.raises(IngestError, match="not empty"):
        ingest_folder(folder, out, log=lambda *_: None)


def test_captions_jsonl_and_val_split(tmp_path):
    src = tmp_path / "in"
    (src / "sub").mkdir(parents=True)
    _one(src / "sub" / "a.mp4", "testsrc2", dur=3)
    _one(src / "b.mp4", "mandelbrot", dur=3)
    (src / "captions.jsonl").write_text(
        json.dumps({"file": "sub/a.mp4", "caption": "en testbild", "lang": "sv"}, ensure_ascii=False) + "\n"
        + json.dumps({"file": "b.mp4", "caption": "a fractal", "lang": "en"}) + "\n", encoding="utf-8")
    (src / "PROVENANCE.json").write_text(json.dumps(PROV))
    s = ingest_folder(src, tmp_path / "o", IngestOptions(val_fraction=0.5, scene_threshold=None), log=lambda *_: None)
    rows = [json.loads(l) for l in (tmp_path / "o" / "manifest.jsonl").read_text(encoding="utf-8").splitlines()]
    assert {(r["source_file"], r["lang"], r["caption"]) for r in rows} == {("sub/a.mp4", "sv", "en testbild"), ("b.mp4", "en", "a fractal")}
    assert len({r["split"] for r in rows if r["source_file"] == "sub/a.mp4"}) == 1      # a source never spans splits
    assert s["train_clips"] + s["val_clips"] == s["clips"]
